// Package calibrate turns the engine's stated confidence into a calibrated
// probability (D160). The map is fitted on the development rows of engine-v1
// on Gemini 4 Argon only, generated by eval/charts/build_accuracy.py into
// map.json and embedded here. It is a step function: deterministic, with no
// model call.
//
// It applies only to the identity it was fitted for: engine-v1 (no rules,
// no voting) answered by the primary model. Any other prediction (fallback
// model, textile, Part 102 and pharmaceutical engines) gets none.
package calibrate

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"

	"github.com/kendramoss/wassup-hackathon-2026/backend/internal/domain"
)

//go:embed map.json
var mapJSON []byte

// Step is one block of the map: stated confidence from From upwards (until
// the next step) maps to Calibrated.
type Step struct {
	From       float64 `json:"from"`
	Calibrated float64 `json:"calibrated"`
	N          int     `json:"n"`
	Correct    int     `json:"correct"`
}

// Map is the committed calibration map.
type Map struct {
	Version      string  `json:"version"`
	EnginePrompt string  `json:"engine_prompt"`
	Model        string  `json:"model"`
	FittedOn     string  `json:"fitted_on"`
	Rule         string  `json:"rule"`
	Bar          float64 `json:"bar"`
	BarRule      string  `json:"bar_rule"`
	Steps        []Step  `json:"steps"`
}

// Load decodes and checks the embedded map.
func Load() (Map, error) { return Parse(mapJSON) }

// Parse decodes and checks a map file (claimscheck reads the committed one).
func Parse(b []byte) (Map, error) {
	var m Map
	if err := json.Unmarshal(b, &m); err != nil {
		return Map{}, fmt.Errorf("calibrate: map: %w", err)
	}
	if m.Version == "" || m.EnginePrompt == "" || m.Model == "" || len(m.Steps) == 0 {
		return Map{}, fmt.Errorf("calibrate: map: version, engine_prompt, model and steps are required")
	}
	if !sort.SliceIsSorted(m.Steps, func(i, j int) bool { return m.Steps[i].From < m.Steps[j].From }) {
		return Map{}, fmt.Errorf("calibrate: map: steps must be in increasing order of from")
	}
	for i, s := range m.Steps {
		if s.Calibrated < 0 || s.Calibrated > 1 || (i > 0 && s.Calibrated < m.Steps[i-1].Calibrated) {
			return Map{}, fmt.Errorf("calibrate: map: step %d: calibrated values must be in [0, 1] and never decrease", i)
		}
	}
	if m.Bar <= 0 || m.Bar > 1 {
		return Map{}, fmt.Errorf("calibrate: map: bar %v, want (0, 1]", m.Bar)
	}
	return m, nil
}

// Must returns the embedded map and panics if it is broken (a build-time
// artefact; its test runs on every build).
func Must() Map {
	m, err := Load()
	if err != nil {
		panic(err)
	}
	return m
}

// Value maps a stated confidence: the step at or below it, or the lowest
// step for a value under every step (the same rule as the eval's
// isotonic_apply).
func (m Map) Value(stated float64) float64 {
	v := m.Steps[0].Calibrated
	for _, s := range m.Steps {
		if stated >= s.From {
			v = s.Calibrated
		}
	}
	return v
}

// Applies reports whether the map was fitted for this prediction: engine-v1
// unmodified (no rules, no reasoning, no voting) answered by the model the
// map names.
func (m Map) Applies(p domain.Prediction) bool {
	return p.Trace.PromptVersion == m.EnginePrompt && p.Trace.Identity() == m.Model && p.VoteAgreement == ""
}

// Apply sets p's calibrated probability and the map version when the map
// applies, and clears them otherwise (a stored value from another map never
// survives).
func (m Map) Apply(p domain.Prediction) domain.Prediction {
	p.CalibratedConfidence, p.Calibration = nil, ""
	if !m.Applies(p) {
		return p
	}
	v := m.Value(p.Confidence)
	p.CalibratedConfidence, p.Calibration = &v, m.Version
	return p
}

// Scored is one evaluated prediction: its stated confidence and whether it
// was right.
type Scored struct {
	Stated float64
	OK     bool
}

// Report compares stated confidence and the calibrated probability on a set
// of scored predictions. ECEStated and ECECalibrated use one bin per distinct
// value on each side (the definition eval/charts/build_accuracy.py uses);
// ECEStatedOnCalibratedBins scores the same stated values on the map's coarser
// partition so the bin-merging effect can be stated separately (D262, #493).
type Report struct {
	N                         int
	Accuracy                  float64
	MeanStated                float64
	MeanCalibrated            float64
	ECEStated                 float64
	ECECalibrated             float64
	ECEStatedOnCalibratedBins float64
	StatedLevels              int
	CalibratedLevels          int
}

// Evaluate maps every row and reports both calibrations.
func (m Map) Evaluate(rows []Scored) Report {
	r := Report{N: len(rows)}
	if r.N == 0 {
		return r
	}
	stated, cal := make([]float64, len(rows)), make([]float64, len(rows))
	ok := make([]bool, len(rows))
	k := 0
	for i, x := range rows {
		stated[i], cal[i], ok[i] = x.Stated, m.Value(x.Stated), x.OK
		r.MeanStated += stated[i]
		r.MeanCalibrated += cal[i]
		if x.OK {
			k++
		}
	}
	n := float64(r.N)
	r.Accuracy, r.MeanStated, r.MeanCalibrated = float64(k)/n, r.MeanStated/n, r.MeanCalibrated/n
	r.ECEStated, r.ECECalibrated = eceLevels(stated, ok), eceLevels(cal, ok)
	r.ECEStatedOnCalibratedBins = eceOnPartition(stated, cal, ok)
	r.StatedLevels = distinctLevels(stated)
	r.CalibratedLevels = distinctLevels(cal)
	return r
}

func distinctLevels(p []float64) int {
	seen := map[float64]bool{}
	for _, v := range p {
		seen[v] = true
	}
	return len(seen)
}

// eceOnPartition scores p using the bins of partition. The per-bin sums are
// accumulated in row order and the bins read in sorted order, so the float is
// stable across runs even though the map's iteration order is not.
func eceOnPartition(p, partition []float64, ok []bool) float64 {
	type bin struct {
		n, k int
		sum  float64
	}
	bins := map[float64]*bin{}
	for i, v := range partition {
		b := bins[v]
		if b == nil {
			b = &bin{}
			bins[v] = b
		}
		b.n++
		b.sum += p[i]
		if ok[i] {
			b.k++
		}
	}
	vals := make([]float64, 0, len(bins))
	for v := range bins {
		vals = append(vals, v)
	}
	sort.Float64s(vals)
	tot := 0.0
	for _, v := range vals {
		b := bins[v]
		d := float64(b.k)/float64(b.n) - b.sum/float64(b.n)
		if d < 0 {
			d = -d
		}
		tot += float64(b.n) * d
	}
	return tot / float64(len(p))
}

func eceLevels(p []float64, ok []bool) float64 {
	type bin struct{ n, k int }
	bins := map[float64]*bin{}
	for i, v := range p {
		b := bins[v]
		if b == nil {
			b = &bin{}
			bins[v] = b
		}
		b.n++
		if ok[i] {
			b.k++
		}
	}
	vals := make([]float64, 0, len(bins))
	for v := range bins {
		vals = append(vals, v)
	}
	sort.Float64s(vals) // a fixed summation order: the same float every run
	tot := 0.0
	for _, v := range vals {
		b := bins[v]
		d := float64(b.k)/float64(b.n) - v
		if d < 0 {
			d = -d
		}
		tot += float64(b.n) * d
	}
	return tot / float64(len(p))
}
